    approver_id uuid,
    approver_email text,
    policy_id uuid,
    title text NOT NULL,
    description text,
    total_amount numeric(20,4) DEFAULT 0 NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
